cat > wrangler.jsonc <<'EOF'
{
  "$schema": "node_modules/wrangler/config-schema.json",
  "name": "langchain-nextjs-template",
  "main": ".open-next/worker.js",
  "compatibility_date": "2026-11-01",
  "compatibility_flags": ["nodejs_compat", "global_fetch_strictly_public"],
  "assets": {
    "directory": ".open-next/assets",
    "binding": "ASSETS"
  },
  "services": [
    {
      // Self-reference binding required by OpenNext; must match "name" above.
      "binding": "WORKER_SELF_REFERENCE",
      "service": "langchain-nextjs-template"
    }
  ],
  "observability": {
    "enabled": true
  }
  // No R2 incremental cache or Images binding: every page here is static or a
  // dynamic API route, and next/image is not used. Both would need billing set up.
  //
  // Secrets (OPENAI_API_KEY, SERPAPI_API_KEY, SUPABASE_URL, SUPABASE_PRIVATE_KEY, ...)
  // are set with `npx wrangler secret put NAME`, never committed here.
}
EOF
cat > open-next.config.ts <<'EOF'
import { defineCloudflareConfig } from "@opennextjs/cloudflare";

// No incremental cache override: the app has no ISR or fetch caching to persist,
// so it runs without an R2 bucket (which would require billing to be enabled).
export default defineCloudflareConfig({});
EOF
